/// <summary>
/// The <c>AVAWHSProcessGuidePromptPrinterCurrentPageBuilder</c> class builds a page that allows the user to the current selected printer
/// </summary>
[
    ProcessGuidePageBuilderName(classStr(AVAWHSProcessGuidePromptCurrentPrinterPageBuilder))
]
class AVAWHSProcessGuidePromptCurrentPrinterPageBuilder extends ProcessGuidePageBuilder
{
}

Method.Source:
protected final void addDataControls(ProcessGuidePage _page)
{ 
    WhsrfPassthrough            pass;
    SysCorpNetActivePrinters    sysCorpNetActivePrinters;

    pass                        = controller.parmSessionState().parmPass();
    sysCorpNetActivePrinters    = SysCorpNetActivePrinters::avaFindByPrinterName(WHSWorkUserSession::find(pass.parmUserId()).AVAPrinterCode);

    if (sysCorpNetActivePrinters)
    { 
        _page.addLabel(ProcessGuideDataTypeNames::UndefinedType, strFmt("@NDX:AVAPrinterCode"   + ': %1', sysCorpNetActivePrinters.PrinterName), extendedTypeNum(WHSRFUndefinedDataType));
        _page.addLabel(ProcessGuideDataTypeNames::UndefinedType, strFmt("@SYS7576"              + ': %1', sysCorpNetActivePrinters.Description), extendedTypeNum(WHSRFUndefinedDataType));
        _page.addLabel(ProcessGuideDataTypeNames::UndefinedType, strFmt("@SYS26604"             + ': %1', sysCorpNetActivePrinters.PrinterPath), extendedTypeNum(WHSRFUndefinedDataType));
    }
    else
    { 
        _page.addLabel(ProcessGuideDataTypeNames::UndefinedType, "@NDX:AVANoPrinterSelected", extendedTypeNum(WHSRFUndefinedDataType));
    }
}

protected final void addActionControls(ProcessGuidePage _page)
{ 
    #ProcessGuideActionNames 

    _page.addButton(step.createAction(#ActionBackProcess), true);
    _page.addButton(step.createAction(#ActionOK), false, "@NDX:AVAChangePrinter");
    _page.addButton(step.createAction(#ActionCancelExitProcess));
}
